sys_script_email.script:
(function runMailScript( /* GlideRecord */ current, /* TemplatePrinter */ template,
    /* Optional EmailOutbound */
    email, /* Optional GlideRecord */ email_action,
    /* Optional GlideRecord */
    event) {
    var now = new GlideDateTime()

    var grNeedIt = new GlideRecord('x_58872_needit_needit_task');
    grNeedIt.addQuery('due_date', '<=', now);
    grNeedIt.addQuery('state', '<', 3);
    grNeedIt.addQuery('assigned_to', current.assigned_to);
    grNeedIt.query();

    template.print('In addition to this overdue NeedIt Task, you have ' + (grNeedIt.getRowCount() - 1) + ' more overdue NeedIt Tasks.');


})(current, template, email, email_action, event);
